const DISMISS_COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000;
/**
 * 检查是否应跳过生成：同类型 + 同触发类型的建议，如果已存在且未过期则跳过。
 * - applied = true → 已处理，跳过
 * - dismissedAt 在 7 天内 → 冷却中，跳过
 * - dismissedAt 超过 7 天或不存在 → 允许重新生成
 */
function isDuplicateSuggestion(existing, type, triggeredByType) {
    const now = Date.now();
    return existing.some(e => {
        if (e.type !== type || e.triggeredBy.type !== triggeredByType)
            return false;
        if (e.applied)
            return true;
        if (e.dismissedAt && (now - new Date(e.dismissedAt).getTime()) < DISMISS_COOLDOWN_MS)
            return true;
        return false;
    });
}
