function markSuggestionApplied(blueprintId, suggestionId) {
    const list = getSuggestions(blueprintId);
    if (!list)
        return false;
    const s = list.find(x => x.id === suggestionId);
    if (!s)
        return false;
    s.applied = true;
    // 采集应用前的健康状态用于 outcome 追踪
    const beforeSnapshot = (0, team_observer_1.getLatestSnapshot)(blueprintId);
    const beforeScore = beforeSnapshot?.overallScore ?? 0;
    // 提取建议关联的缝隙维度（用于后续按维度统计）
    const relatedDimension = s.triggeredBy.dimension || null;
    const eventId = `evt_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    recordEvolutionEvent(blueprintId, {
        id: eventId,
        timestamp: new Date().toISOString(),
        type: 'suggestion_applied',
        suggestionId,
        description: `优化建议已应用: ${s.title}`,
        beforeState: beforeSnapshot ? {
            overallScore: beforeScore,
            dimension: relatedDimension,
            gaps: beforeSnapshot.gaps.map(g => ({ dimension: g.dimension, score: 100 - (g.conflictRate * 60 + g.escalateRate * 30 + g.interventionRate * 10) * 100 })),
        } : undefined,
    });
    // 注册 pending outcome 追踪
    let pending = pendingOutcomes.get(blueprintId);
    if (!pending) {
        pending = [];
        pendingOutcomes.set(blueprintId, pending);
    }
    pending.push({
        suggestionId,
        suggestionTitle: s.title,
        eventId,
        blueprintId,
        beforeScore,
        appliedAt: new Date().toISOString(),
        dimension: relatedDimension,
    });
    persistPendingOutcomes();
    (0, storage_1.saveSuggestionsDB)(blueprintId, list);
    return true;
}
function markSuggestionDismissed(blueprintId, suggestionId) {
    const list = getSuggestions(blueprintId);
    if (!list)
        return false;
    const s = list.find(x => x.id === suggestionId);
    if (!s)
        return false;
    // 7 天冷却：设置 dismissedAt 但不标记 applied，冷却期后同类型可重新生成
    s.dismissedAt = new Date().toISOString();
    recordEvolutionEvent(blueprintId, {
        id: `evt_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        timestamp: new Date().toISOString(),
        type: 'suggestion_dismissed',
        suggestionId,
        description: `优化建议已忽略(7天冷却): ${s.title}`,
    });
    (0, storage_1.saveSuggestionsDB)(blueprintId, list);
    return true;
}
// ================================================================
// 进化结果追踪（Outcome Tracking）
// ================================================================
const pendingOutcomes = new Map();
// 模块初始化：加载持久化的 pending outcomes
loadPendingOutcomes();
/** 加载持久化的 pending outcomes */
function loadPendingOutcomes() {
    try {
        const loaded = (0, storage_1.loadPendingOutcomesDB)();
        for (const po of loaded) {
            let list = pendingOutcomes.get(po.blueprintId);
            if (!list) {
                list = [];
                pendingOutcomes.set(po.blueprintId, list);
            }
            list.push(po);
        }
    }
    catch (err) {
        console.warn('[evolution-engine] 加载 pending outcomes 失败:', err.message);
    }
}
function persistPendingOutcomes() {
    const all = [];
    for (const list of pendingOutcomes.values()) {
        all.push(...list);
    }
    if (all.length > 0) {
        (0, storage_1.savePendingOutcomesDB)(all);
    }
}
/** 应用建议后评估效果 */
function evaluateOutcomes(blueprintId, currentHealth) {
    const pending = pendingOutcomes.get(blueprintId);
    if (!pending || pending.length === 0)
        return;
    const remaining = [];
    for (const po of pending) {
        const afterScore = currentHealth.overallScore;
        const improved = afterScore > po.beforeScore;
        const degraded = afterScore < po.beforeScore - 5;
        const delta = afterScore - po.beforeScore;
        let direction = 'unchanged';
        if (delta > 0)
            direction = 'improved';
        else if (delta < -5)
            direction = 'degraded';
        const event = {
            id: `evt_outcome_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
            timestamp: new Date().toISOString(),
            type: 'suggestion_applied',
            suggestionId: po.suggestionId,
            description: `优化效果评估: ${po.suggestionTitle} — ${direction === 'improved' ? '改善' : direction === 'degraded' ? '退化' : '无明显变化'} (${po.beforeScore}→${afterScore}, ${delta >= 0 ? '+' : ''}${delta})`,
            beforeState: { overallScore: po.beforeScore },
            afterState: { overallScore: afterScore },
            outcome: {
                metric: 'overallScore',
                before: po.beforeScore,
                after: afterScore,
                improved: direction === 'improved',
                effect: { direction, delta },
            },
        };
        recordEvolutionEvent(blueprintId, event);
        const elapsed = Date.now() - new Date(po.appliedAt).getTime();
        if (elapsed < 10 * 60 * 1000 && !improved && degraded) {
            remaining.push(po);
        }
    }
    if (remaining.length > 0) {
        pendingOutcomes.set(blueprintId, remaining);
    }
    else {
        pendingOutcomes.delete(blueprintId);
    }
    persistPendingOutcomes();
}
/** P0-1: 统计 Evolution 建议的效果比例（improved/degraded/unchanged） */
function getOutcomeStats(blueprintId) {
    const events = getEvolutionHistory(blueprintId);
    const evaluated = events.filter(e => e.outcome?.effect);
    let improved = 0;
    let degraded = 0;
    let unchanged = 0;
    const byDimension = {};
    let lastEvaluated;
    for (const e of evaluated) {
        const dir = e.outcome.effect.direction;
        if (dir === 'improved')
            improved++;
        else if (dir === 'degraded')
            degraded++;
        else
            unchanged++;
        const dim = e.beforeState?.dimension || 'unknown';
        if (!byDimension[dim])
            byDimension[dim] = { improved: 0, degraded: 0, unchanged: 0 };
        if (dir === 'improved')
            byDimension[dim].improved++;
        else if (dir === 'degraded')
            byDimension[dim].degraded++;
        else
            byDimension[dim].unchanged++;
        if (!lastEvaluated || e.timestamp > lastEvaluated.evaluatedAt) {
            lastEvaluated = {
                suggestionId: e.suggestionId || '',
                description: e.description,
                before: e.outcome.before,
                after: e.outcome.after,
                delta: e.outcome.effect.delta,
                direction: dir,
                evaluatedAt: e.timestamp,
            };
        }
    }
    return {
        total: evaluated.length,
        improved,
        degraded,
        unchanged,
        improvementRate: evaluated.length > 0 ? improved / evaluated.length : 0,
        byDimension,
        lastEvaluated,
    };
}
// ================================================================
// 进化事件历史
// ================================================================
function recordEvolutionEvent(blueprintId, event) {
    let list = evolutionHistory.get(blueprintId);
    if (!list) {
        list = (0, storage_1.loadEvolutionEventsDB)(blueprintId);
        evolutionHistory.set(blueprintId, list);
    }
    list.push(event);
    while (list.length > MAX_HISTORY)
        list.shift();
    (0, storage_1.saveEvolutionEventDB)(blueprintId, event);
}
function getEvolutionHistory(blueprintId, limit = 50) {
    let list = evolutionHistory.get(blueprintId);
    if (!list) {
        list = (0, storage_1.loadEvolutionEventsDB)(blueprintId);
        evolutionHistory.set(blueprintId, list);
    }
    return (list || []).slice(-limit);
}
// ================================================================
// 周期分析入口
// ================================================================
function runEvolutionCycle(blueprintId, teamName, options) {
    const newSuggestions = analyzeAndGenerateSuggestions(blueprintId, teamName, options);
    const snapshot = (0, team_observer_1.getLatestSnapshot)(blueprintId);
    const history = getEvolutionHistory(blueprintId);
    return {
        snapshot: snapshot,
        newSuggestions,
        history,
    };
}
